      return row === undefined ? null : hydrateRow('ai_insights', InsightRowSchema, row);
    },

    findById(id: number): Insight | null {
      const row = byIdStmt.get(id);
      return row === undefined ? null : hydrateRow('ai_insights', InsightRowSchema, row);
