 * Every colour pair here clears WCAG AA for body text against its own surface. Severity is
 * never signalled by colour alone — each badge also carries a glyph and a word.
 */

:root {
  /* Spacing — a single scale, so nothing is ever positioned with an arbitrary pixel value. */
  --space-1: 0.25rem;
