  --text-md: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.375rem;
  --text-2xl: 1.75rem;

  --shadow-sm: 0 1px 2px rgb(15 23 42 / 8%);
  --shadow-md: 0 4px 12px rgb(15 23 42 / 10%);
  --shadow-lg: 0 16px 48px rgb(15 23 42 / 18%);

  --header-height: 3.5rem;
  --drawer-width: min(34rem, 100vw);

  /* Light scheme */
  --surface-page: #f6f7f9;
