toolUseResult.originalFile:
@import './tokens.css';

/*
 * Base layer and the layout-safety rules this application depends on.
 *
 * The rules under "overflow containment" are not cosmetic. Alert descriptions are written by
 * field equipment and can contain 55-character unbroken asset identifiers; without them, one
 * such string pushes a table column past its neighbour and text lands on top of text. They are
 * asserted automatically by the Playwright layout audit rather than left to inspection.
 */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.5;
  color: var(--text-primary);
  background: var(--surface-page);
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
h4,
p,
figure {
  margin: 0;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

/* ------------------------------------------------------- overflow containment */

/*
 * A flex or grid child defaults to `min-width: auto`, which refuses to shrink below its
 * content. That single default is the cause of almost every "text escaping its box" bug in a
 * dashboard layout, so it is corrected globally rather than patched per component.
 */
.stack,
.row,
.cell,
[data-shrinkable] {
  min-width: 0;
}

/* Long machine-generated tokens wrap instead of pushing their container wider. */
.wrap-anywhere {
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* Single-line truncation with the full value still available on hover and to a screen reader. */
.truncate {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
}

