}

.medium {
  background: var(--severity-medium-soft);
  color: var(--severity-medium);
  border-color: color-mix(in srgb, var(--severity-medium) 35%, transparent);
}

.low {
  background: var(--severity-low-soft);
  color: var(--severity-low);
  border-color: color-mix(in srgb, var(--severity-low) 35%, transparent);
}

/* Status ------------------------------------------------------------------ */

.new {
  background: var(--status-new-soft);
  color: var(--status-new);
}

.acknowledged {
  background: var(--status-acknowledged-soft);
  color: var(--status-acknowledged);
}

.in_progress {
  background: var(--status-in_progress-soft);
  color: var(--status-in_progress);
