.breach {
  composes: chip from global;
  background: var(--danger-soft);
  color: var(--danger);
  border: 1px solid color-mix(in srgb, var(--danger) 40%, transparent);
}

.attention {
  composes: chip from global;
  background: var(--accent-soft);
  color: var(--accent-text);
}

