import { useEffect, useState } from 'react';

/**
 * Drives the table/card switch from a media query rather than rendering both and hiding one.
 * Two copies of every row in the DOM would double the work for a screen reader and give the
 * accessibility audit duplicate content to complain about.
 */
export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(() =>
    typeof window === 'undefined' ? false : window.matchMedia(query).matches,
  );

  useEffect(() => {
    const list = window.matchMedia(query);
    const onChange = (event: MediaQueryListEvent): void => {
      setMatches(event.matches);
    };
    setMatches(list.matches);
    list.addEventListener('change', onChange);
    return () => {
      list.removeEventListener('change', onChange);
    };
  }, [query]);

  return matches;
}

.strip {
  display: grid;
  /* `minmax(0, 1fr)` rather than `1fr`: the zero minimum is what lets a tile shrink instead of
     pushing its neighbour, which is the difference between a tidy row and overlapping text. */
  grid-template-columns: repeat(auto-fit, minmax(min(11rem, 100%), 1fr));
  gap: var(--space-3);
}

.tile {
  composes: card from global;
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  padding: var(--space-3) var(--space-4);
  min-width: 0;
  text-align: left;
  border-left: 3px solid var(--border-subtle);
}

button.tile {
  cursor: pointer;
  transition: border-color 120ms ease, background-color 120ms ease;
}

button.tile:hover {
  background: var(--surface-hover);
}

button.tile[aria-pressed='true'] {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.value {
  font-size: var(--text-2xl);
  font-weight: 650;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--text-primary);
}

.label {
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
  min-width: 0;
  overflow-wrap: anywhere;
}

.hint {
  font-size: var(--text-xs);
  color: var(--text-secondary);
  min-width: 0;
  overflow-wrap: anywhere;
}

.urgent {
  border-left-color: var(--severity-critical);
}

.urgent .value {
  color: var(--severity-critical);
}

.warn {
  border-left-color: var(--severity-high);
}

.calm {
  border-left-color: var(--success);
}

.neutral {
  border-left-color: var(--accent);
}

