input.content:
.panel {
  background: var(--surface-raised);
  border: 1px solid var(--border-subtle);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
  overflow: hidden;
}

/* The table scrolls sideways inside its own box. The page body never does — a dashboard that
   scrolls horizontally as a whole is a dashboard whose header has left the screen. */
.scroller {
  overflow-x: auto;
  overscroll-behavior-x: contain;
}

.table {
  width: 100%;
  min-width: 60rem;
  border-collapse: collapse;
  /* Fixed layout is what makes the column widths below authoritative: content adapts to the
     column instead of the column stretching to fit a 55-character asset id. */
  table-layout: fixed;
}

.table th,
.table td {
  padding: var(--space-3) var(--space-3);
  text-align: left;
  vertical-align: top;
  overflow: hidden;
}

.table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
