.panel {
  composes: card from global;
  border-left: 3px solid var(--severity-critical);
  overflow: hidden;
}

.head {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  flex-wrap: wrap;
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border-subtle);
  min-width: 0;
}

.title {
  font-size: var(--text-md);
  font-weight: 650;
}

.subtitle {
  font-size: var(--text-xs);
  color: var(--text-muted);
  min-width: 0;
}

.viewAll {
  margin-left: auto;
  border: none;
  background: none;
  padding: 0;
  color: var(--accent);
  font-size: var(--text-xs);
  font-weight: 600;
  cursor: pointer;
  text-decoration: underline;
  flex: 0 0 auto;
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.item {
  display: grid;
  /* Fixed rail for the rank, then a column that is free to shrink. `minmax(0, 1fr)` is what
     stops a long title from widening the row and colliding with the badges. */
  grid-template-columns: 1.75rem minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-3) var(--space-4);
  border: none;
  border-top: 1px solid var(--border-subtle);
  background: none;
  text-align: left;
  cursor: pointer;
  min-width: 0;
}

.item:first-child {
  border-top: none;
}

.item:hover {
  background: var(--surface-hover);
}

.rank {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.main {
  display: flex;
