              totalPages={alerts.data.totalPages}
              onPage={(page) => {
                setFilters({ ...filters, page });
              }}
            />
          )}
        </section>
      </main>

      {selectedAlertId !== null && (
        <AlertDrawer
          key={selectedAlertId}
          alertId={selectedAlertId}
          operator={operator}
          now={now}
          onClose={() => {
            selectAlert(null);
          }}
          onChanged={refreshBoard}
        />
      )}
    </div>
  );
}

